                var x0 = new floatN(2, Allocator.Temp, true);
                x0[0] = (float)rng.NextFloat(-2f, 2f);
                x0[1] = (float)rng.NextFloat(-2f, 2f);

                var info = MPC.solve(ref mpc, in x0, in reference, ref u0);
                AssertTrue(info.status == MPCStatus.Optimal || info.status == MPCStatus.MaxIterations);

                float u0lqr = -(K[0, 0] * x0[0] + K[0, 1] * x0[1]);
                AssertClose(u0[0], u0lqr, LqrU0Tol());

                x0.Dispose();
            }

            u0.Dispose(); reference.Dispose(); mpc.Dispose(); K.Dispose();
            A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
