        // ============================ (d) warm-start health ============================

        // Receding-horizon run from a displaced start (x0=(5,0), tight input bounds [-0.5,0.5], N=8):
        // active-set churn must collapse to a small bound after a short initial transient.
        void WarmStartChurnBound()
        {
            var A = Mat2(1, 1, 0, 1); var B = ColVec2(0, 1); var Q = Eye(2); var R = R1(1);
            var uLo = Vec1((float)(-0.5)); var uHi = Vec1((float)0.5);
            var mpc = new floatMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

            var x = Vec2(5, 0);
            var reference = new floatN(2, Allocator.Temp);   // zero-initialized: track to the origin
            var u0 = new floatN(1, Allocator.Temp, true);

            const int steadyFrame = 8;
            const int totalFrames = 20;
            for (int f = 0; f < totalFrames; f++)
            {
                var info = MPC.solve(ref mpc, in x, in reference, ref u0);
                AssertTrue(info.status == MPCStatus.Optimal || info.status == MPCStatus.MaxIterations);
                if (f >= steadyFrame) AssertLE(info.activeSetChanges, 3);

                float x0n = x[0] + x[1];
                float x1n = x[1] + u0[0];
                x[0] = x0n; x[1] = x1n;
            }

            x.Dispose(); reference.Dispose(); u0.Dispose(); mpc.Dispose();
            A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
        }

        // At a fixed later frame, a warm-started sequence's own iteration count must not exceed a
        // freshly-constructed (cold) state solving the IDENTICAL point (same optimum either way -- a
        // strictly convex QP's solution does not depend on warm-starting, only the pivot count does).
        void WarmIterationsBeatCold()
        {
            var A = Mat2(1, 1, 0, 1); var B = ColVec2(0, 1); var Q = Eye(2); var R = R1(1);
            var uLo = Vec1((float)(-0.5)); var uHi = Vec1((float)0.5);
            var mpcWarm = new floatMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

            var x = Vec2(5, 0);
            var reference = new floatN(2, Allocator.Temp);   // zero-initialized: track to the origin
            var u0 = new floatN(1, Allocator.Temp, true);

            const int targetFrame = 10;
            var xAtTarget = new floatN(2, Allocator.Temp, true);
            int warmIters = 0;
            for (int f = 0; f <= targetFrame; f++)
            {
                if (f == targetFrame) xAtTarget.CopyFrom(x);
                var info = MPC.solve(ref mpcWarm, in x, in reference, ref u0);
                if (f == targetFrame) warmIters = info.iterations;

                float x0n = x[0] + x[1];
                float x1n = x[1] + u0[0];
                x[0] = x0n; x[1] = x1n;
            }

            var mpcCold = new floatMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);
            var u0c = new floatN(1, Allocator.Temp, true);
            var coldInfo = MPC.solve(ref mpcCold, in xAtTarget, in reference, ref u0c);
            AssertTrue(coldInfo.status == MPCStatus.Optimal || coldInfo.status == MPCStatus.MaxIterations);

            AssertLE(warmIters, coldInfo.iterations);

            u0c.Dispose(); mpcCold.Dispose(); xAtTarget.Dispose();
            x.Dispose(); reference.Dispose(); u0.Dispose(); mpcWarm.Dispose();
            A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
        }

        // The persistent warm path (MPC.solve carries qpFactor/qpReduced across ticks, reusing them
        // whole when the working set has not moved) must land on the SAME optimum a from-scratch COLD
        // solve of the IDENTICAL condensed QP finds -- EVERY frame, across both the steady-state reuse
        // ticks and the working-set-changing (rebuild) ticks. The condensed Hessian is PD (R > 0), so
        // the minimizer is unique: cross-tick reuse cannot silently drift the answer. x0=(5,0) with a
        // tight [-0.5,0.5] input bound saturates early (working-set churn) then relaxes to steady state
        // -- exercising both code paths in one run.
        void WarmPersistentMatchesColdEachFrame()
        {
            var A = Mat2(1, 1, 0, 1); var B = ColVec2(0, 1); var Q = Eye(2); var R = R1(1);
            var uLo = Vec1((float)(-0.5)); var uHi = Vec1((float)0.5);
            var mpc = new floatMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

            var x = Vec2(5, 0);
            var reference = new floatN(2, Allocator.Temp);   // track to the origin
            var u0 = new floatN(1, Allocator.Temp, true);

            int nz = mpc.nz;
            var xCold = new floatN(nz, Allocator.Temp, true);
            double objTol = 3e-3;
            float zTol = 5e-3f;

            for (int f = 0; f < 16; f++)
            {
                var info = MPC.solve(ref mpc, in x, in reference, ref u0);
                AssertTrue(info.status == MPCStatus.Optimal || info.status == MPCStatus.MaxIterations);

                // Independently COLD-solve the same condensed QP MPC just warm-solved: its gradient and
                // general RHS are still in cScratch/bScratch, the warm solution in z. Same optimum since
                // H is PD -- pins that the persistent reuse produced the true minimizer this frame.
                for (int i = 0; i < nz; i++) xCold[i] = (float)0;
                var coldInfo = QP.solve(in mpc.H, in mpc.cScratch, in mpc.Arows, in mpc.bScratch, in mpc.senses,
                                        in mpc.xl, in mpc.xu, ref xCold, out double objCold, 0);
                AssertTrue(coldInfo.status == QPStatus.Optimal);
                AssertCloseD(info.objective, objCold, objTol);
                for (int i = 0; i < nz; i++) AssertClose(mpc.z[i], xCold[i], zTol);

                float x0n = x[0] + x[1];
                float x1n = x[1] + u0[0];
                x[0] = x0n; x[1] = x1n;
            }

            xCold.Dispose();
            x.Dispose(); reference.Dispose(); u0.Dispose(); mpc.Dispose();
            A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
        }

        // ============================ (e) prestabilization correctness ============================

        // Prestabilization is a PURE change of coordinates, so it must reproduce the IDENTICAL
        // physical answer as solving the SAME (A,B,Q,R,uLo,uHi) problem without it. x0=(3,1.9) is
        // the SAME binding scenario as SaturatedMatchesOracle (u0 saturates at uLo=-2), reused here
        // as the discriminating case.
        void PrestabBindingBoundMatchesNonPrestab()
        {
            var A = Mat2(1, 1, 0, 1); var B = ColVec2(0, 1); var Q = Eye(2); var R = R1(1);
            var uLo = Vec1((float)(-2)); var uHi = Vec1((float)2);

            var Kstab = new floatMxN(1, 2, Allocator.Temp);
            var lqrInfo = LQR.lqr(in A, in B, in Q, in R, ref Kstab);
            AssertTrue(lqrInfo.status == LQRStatus.Converged);

            var mpcPlain = new floatMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);
            var mpcPrestab = new floatMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi,
                                                default, default, default, default(floatN), (float)0, (float)0, in Kstab);

            var x0 = Vec2(3, (float)1.9);
            var reference = new floatN(2, Allocator.Temp);   // zero-initialized: track to the origin
            var u0Plain = new floatN(1, Allocator.Temp, true);
            var u0Prestab = new floatN(1, Allocator.Temp, true);

            var infoPlain = MPC.solve(ref mpcPlain, in x0, in reference, ref u0Plain);
            var infoPrestab = MPC.solve(ref mpcPrestab, in x0, in reference, ref u0Prestab);
            AssertTrue(infoPlain.status == MPCStatus.Optimal || infoPlain.status == MPCStatus.MaxIterations);
            AssertTrue(infoPrestab.status == MPCStatus.Optimal || infoPrestab.status == MPCStatus.MaxIterations);

            // (i) reconstruct u0 = -Kstab*x0 + v0 INDEPENDENTLY (reading mpcPrestab.Kstab/z directly,
            // not trusting MPC.solve's own internal ExtractU0 conversion) and check it respects the
            // physical input bound -- the off-by-one bug placed this wildly outside [-2,2].
            float uRecon = -(mpcPrestab.Kstab[0, 0] * x0[0] + mpcPrestab.Kstab[0, 1] * x0[1]) + mpcPrestab.z[0];
            AssertClose(uRecon, u0Prestab[0], OracleU0Tol());
            AssertTrue(uRecon >= uLo[0] - OracleU0Tol() && uRecon <= uHi[0] + OracleU0Tol());

            // (ii) same physical problem, different coordinates -- must agree to tight tolerance.
            AssertClose(u0Prestab[0], u0Plain[0], OracleU0Tol());
            AssertClose(u0Prestab[0], (float)(-2.0), OracleU0Tol());   // both saturate at uLo, per the prototype

            x0.Dispose(); reference.Dispose(); u0Plain.Dispose(); u0Prestab.Dispose();
            mpcPlain.Dispose(); mpcPrestab.Dispose(); Kstab.Dispose();
            A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
        }

        // ================================ helpers ================================

        static floatMxN Mat2(float a, float b, float c, float d)
        {
            var M = new floatMxN(2, 2, Allocator.Temp);
            M[0, 0] = a; M[0, 1] = b; M[1, 0] = c; M[1, 1] = d;
            return M;
        }

        static floatMxN ColVec2(float a, float b)
        {
            var M = new floatMxN(2, 1, Allocator.Temp);
            M[0, 0] = a; M[1, 0] = b;
            return M;
        }

        static floatMxN Eye(int n)
        {
            var M = new floatMxN(n, n, Allocator.Temp);
            for (int i = 0; i < n; i++) M[i, i] = (float)1;
            return M;
        }

        static floatMxN R1(float v)
        {
            var M = new floatMxN(1, 1, Allocator.Temp);
            M[0, 0] = v;
            return M;
        }

        static floatMxN WallRow()
        {
            var M = new floatMxN(1, 2, Allocator.Temp);
            M[0, 0] = (float)1; M[0, 1] = (float)0;
            return M;
        }

        static floatN Vec1(float v)
        {
            var vec = new floatN(1, Allocator.Temp, true);
            vec[0] = v;
            return vec;
        }

        static floatN Vec2(float a, float b)
        {
            var vec = new floatN(2, Allocator.Temp, true);
            vec[0] = a; vec[1] = b;
            return vec;
        }

        // ---- Fail[0..3] diagnostic asserts (same shape as ControlLQRTests.float.cs) ----
        void AssertTrue(bool cond)
        {
            if (!cond && Fail[0] == (float)0) { Fail[0] = (float)1; Fail[1] = (float)0; Fail[2] = (float)1; Fail[3] = (float)0; }
            Assert.IsTrue(cond);
        }

        void AssertLE(int got, int limit)
        {
            if (!(got <= limit) && Fail[0] == (float)0) { Fail[0] = (float)1; Fail[1] = (float)got; Fail[2] = (float)limit; Fail[3] = (float)(got - limit); }
            Assert.IsTrue(got <= limit);
        }

        void AssertLEd(double got, double limit)
        {
            if (!(got <= limit) && Fail[0] == (float)0) { Fail[0] = (float)1; Fail[1] = (float)got; Fail[2] = (float)limit; Fail[3] = (float)(got - limit); }
            Assert.IsTrue(got <= limit);
        }

        void AssertClose(float a, float b, float precision)
        {
            float diff = math.abs(a - b);
            if (!(diff <= precision) && Fail[0] == (float)0) { Fail[0] = (float)1; Fail[1] = a; Fail[2] = b; Fail[3] = diff; }
            Assert.IsTrue(diff <= precision);
        }

        void AssertCloseD(double a, double b, double precision)
        {
            double diff = math.abs(a - b);
            if (!(diff <= precision) && Fail[0] == (float)0) { Fail[0] = (float)1; Fail[1] = (float)a; Fail[2] = (float)b; Fail[3] = (float)diff; }
            Assert.IsTrue(diff <= precision);
        }
