    public static Array GetEnums() => Enum.GetValues(typeof(TestJob.TestType));

    [TestCaseSource("GetEnums")]
    public void MPCTests(TestJob.TestType type)
    {
        var fail = new NativeArray<float>(4, Allocator.TempJob);
        try
        {
            new TestJob() { Type = type, Fail = fail }.Run();
            if (fail[0] != (float)0)
                Assert.Fail($"got {fail[1]}, expected/limit {fail[2]}, diff/extra {fail[3]}");
        }
        catch (Exception e)
        {
            if (fail[0] != (float)0)
                Assert.Fail($"{type}: got {fail[1]}, expected/limit {fail[2]}, diff/extra {fail[3]} ({e.Message})");
            throw;
        }
        finally
        {
            fail.Dispose();
        }
    }

    // ---- managed-thread validation throws + disposal (not Burst-job-friendly: constructor exceptions
    // and repeated Dispose() are awkward inside a single IJob.Execute) ----

    [Test]
    public void SolveThrowsOnMismatchedX0()
    {
        var A = new floatMxN(2, 2, Allocator.Temp); A[0, 0] = 1; A[0, 1] = 1; A[1, 1] = 1;
        var B = new floatMxN(2, 1, Allocator.Temp); B[1, 0] = 1;
        var Q = new floatMxN(2, 2, Allocator.Temp); Q[0, 0] = 1; Q[1, 1] = 1;
        var R = new floatMxN(1, 1, Allocator.Temp); R[0, 0] = 1;
        var uLo = new floatN(1, Allocator.Temp, true); uLo[0] = (float)(-1);
        var uHi = new floatN(1, Allocator.Temp, true); uHi[0] = (float)1;
        var mpc = new floatMPCState(2, 1, 4, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

        var badX0 = new floatN(3, Allocator.Temp, true);
        var reference = new floatN(2, Allocator.Temp);   // zero-initialized: track to the origin
        var u0 = new floatN(1, Allocator.Temp, true);
        Assert.Catch<ArgumentException>(() => MPC.solve(ref mpc, in badX0, in reference, ref u0));

        badX0.Dispose(); reference.Dispose(); u0.Dispose(); mpc.Dispose();
        A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
    }

    [Test]
    public void SolveThrowsOnBadReferenceLength()
    {
        var A = new floatMxN(2, 2, Allocator.Temp); A[0, 0] = 1; A[0, 1] = 1; A[1, 1] = 1;
        var B = new floatMxN(2, 1, Allocator.Temp); B[1, 0] = 1;
        var Q = new floatMxN(2, 2, Allocator.Temp); Q[0, 0] = 1; Q[1, 1] = 1;
        var R = new floatMxN(1, 1, Allocator.Temp); R[0, 0] = 1;
        var uLo = new floatN(1, Allocator.Temp, true); uLo[0] = (float)(-1);
        var uHi = new floatN(1, Allocator.Temp, true); uHi[0] = (float)1;
        var mpc = new floatMPCState(2, 1, 4, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

        var x0 = new floatN(2, Allocator.Temp, true);
        var badReference = new floatN(3, Allocator.Temp, true);   // neither n(2) nor N*n(8)
        var u0 = new floatN(1, Allocator.Temp, true);
        Assert.Catch<ArgumentException>(() => MPC.solve(ref mpc, in x0, in badReference, ref u0));

        x0.Dispose(); badReference.Dispose(); u0.Dispose(); mpc.Dispose();
        A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
    }

    [Test]
    public void ConstructorThrowsOnUnstabilizablePair()
    {
        // A's mode with eigenvalue 2 is uncontrollable (B only actuates the second state), mirroring
        // ControlLQRTests.float.cs's own FailureUnstabilizable job -- the auto-DARE terminal cost
        // cannot be computed, so construction must fail rather than silently produce a bad terminal cost.
        var A = new floatMxN(2, 2, Allocator.Temp); A[0, 0] = 2; A[1, 1] = (float)0.5;
        var B = new floatMxN(2, 1, Allocator.Temp); B[1, 0] = 1;
        var Q = new floatMxN(2, 2, Allocator.Temp); Q[0, 0] = 1; Q[1, 1] = 1;
        var R = new floatMxN(1, 1, Allocator.Temp); R[0, 0] = 1;
        var uLo = new floatN(1, Allocator.Temp, true); uLo[0] = (float)(-1);
        var uHi = new floatN(1, Allocator.Temp, true); uHi[0] = (float)1;

        Assert.Catch<ArgumentException>(() => new floatMPCState(2, 1, 4, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi));

        A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
    }

    [Test]
    public void DisposeIsIdempotent()
    {
        var A = new floatMxN(2, 2, Allocator.Temp); A[0, 0] = 1; A[0, 1] = 1; A[1, 1] = 1;
        var B = new floatMxN(2, 1, Allocator.Temp); B[1, 0] = 1;
        var Q = new floatMxN(2, 2, Allocator.Temp); Q[0, 0] = 1; Q[1, 1] = 1;
        var R = new floatMxN(1, 1, Allocator.Temp); R[0, 0] = 1;
        var uLo = new floatN(1, Allocator.Temp, true); uLo[0] = (float)(-1);
        var uHi = new floatN(1, Allocator.Temp, true); uHi[0] = (float)1;
        var mpc = new floatMPCState(2, 1, 4, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

        Assert.IsTrue(mpc.IsCreated);
        mpc.Dispose();
        Assert.DoesNotThrow(() => mpc.Dispose());

        A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
    }
